input.command:
gh api graphql -f query='
{
  repository(owner: "chief-builder-lab", name: "clivsmcp-tier1-issue-triage-4cba9e59") {
    issues(states: OPEN, first: 50) {
      nodes {
        number
        title
        body
        labels(first: 10) {
          nodes { name }
        }
      }
    }
  }
}' --jq '.data.repository.issues.nodes[] | {number, title, body: .body, labels: [.labels.nodes[].name]}'

